    width: 0.25,
    position: [0.27, 0.19, 0.015],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  let lampOn = true;
  let level = 1;
  let pressPulse = 0;

  function applyState() {
    panel.set('state', lampOn ? {
      text: 'ON',
      color: '#c8ffdb',
      backgroundColor: '#28553b',
    } : {
      text: 'OFF',
      color: '#d1d6db',
      backgroundColor: '#3a4046',
    });
    panel.set('hint', {
      text: lampOn
        ? 'Press the lamp to switch it off.'
        : 'Press the lamp to switch it on.',
    });

    powerMaterial.color.setHex(lampOn ? 0x53d790 : 0x59636a);
    powerMaterial.emissive.setHex(lampOn ? 0x36d67f : 0x20272b);
  }

  function toggleLamp() {
    lampOn = !lampOn;
    pressPulse = 1;
    applyState();
  }

  traits(shade, { onPress: toggleLamp });
  traits(arm, { onPress: toggleLamp });
  traits(base, { onPress: toggleLamp });
  traits(powerButton, { onPress: toggleLamp });

  return {
    root,
    update(time, delta) {
      const target = lampOn ? 1 : 0;
      level += (target - level) * (1 - Math.exp(-delta * 12));
      if (Math.abs(target - level) < 0.001) level = target;

      bulbMaterial.emissiveIntensity = 0.03 + level * 2.3;
      innerMaterial.emissiveIntensity = 0.03 + level * 0.9;
      powerMaterial.emissiveIntensity = 0.03 + level * 1.2;

      beamMaterial.opacity = level * 0.055;
      haloMaterial.opacity = level * 0.14;
      poolOuterMaterial.opacity = level * 0.12;
      poolInnerMaterial.opacity = level * 0.18;

      const glowVisible = level > 0.005;
      beam.visible = glowVisible;
      halo.visible = glowVisible;
      poolOuter.visible = glowVisible;
      poolInner.visible = glowVisible;

      pressPulse = Math.max(0, pressPulse - delta * 7);
      powerButton.position.y = 0.038 - pressPulse * 0.004;
      powerButton.scale.y = 1 - pressPulse * 0.3;
    },
  };
}

