      roughness: i >= 2 ? 0.48 : 0.7,
      metalness: i >= 2 ? 0.28 : 0.04,
      side: THREE.DoubleSide,
    });

    // Three quarters of each sphere remain, revealing two radial cut faces.
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(data.outer, 32, 16, Math.PI, Math.PI * 1.5),
      material,
    );
    sphere.name = `${data.name} curved surface`;
    group.add(sphere);

    const cutGeometry = data.inner === 0
      ? new THREE.CircleGeometry(data.outer, 48, cutStart, cutLength)
      : new THREE.RingGeometry(data.inner, data.outer, 48, 1, cutStart, cutLength);

    // Front-facing half-section on the z = 0 plane.
    const cutFront = new THREE.Mesh(cutGeometry, material);
    cutFront.name = `${data.name} front cut face`;
    cutFront.position.z = 0.0002;
    group.add(cutFront);

    // The second exposed half-section, on the x = 0 plane.
    const cutSide = new THREE.Mesh(cutGeometry, material);
    cutSide.name = `${data.name} side cut face`;
    cutSide.rotation.y = -Math.PI / 2;
    cutSide.position.x = -0.0002;
    group.add(cutSide);

    layers.push({ group, material, data });
  }

  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.15, 0.16, 0.03, 48),
    new THREE.MeshStandardMaterial({
      color: 0x252b32,
      roughness: 0.5,
      metalness: 0.45,
    }),
  );
  base.name = 'Earth model stand';
  base.position.set(centerX, 0.015, 0);
  root.add(base);

  const panel = ui(`
    <style>
      .card {
        display: flex;
        flex-direction: column;
        gap: 10px;
        width: 450px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 18px;
        border-width: 1px;
