        background-color: #1a1d22;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
      }
      .subtitle {
        color: #b9c2cf;
        font-size: 19px;
      }
      .layer {
        display: flex;
        flex-direction: row;
        align-items: center;
        gap: 14px;
        width: 450px;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 13px;
        border-width: 1px;
        border-color: #3a414b;
        background-color: #262b32;
      }
      .swatch {
        width: 22px;
        height: 22px;
        border-radius: 11px;
      }
      .crust-swatch { background-color: #83a95c; }
      .mantle-swatch { background-color: #d85d44; }
      .outer-swatch { background-color: #f2a63b; }
      .inner-swatch { background-color: #ffdf80; }
      .layer-copy {
        display: flex;
        flex-direction: column;
        gap: 2px;
      }
      .layer-name {
        color: #ffffff;
        font-size: 23px;
        font-weight: 700;
        text-align: left;
      }
      .layer-sub {
        color: #c4ccd6;
        font-size: 18px;
        text-align: left;
      }
      .detail {
        display: flex;
        flex-direction: column;
        gap: 7px;
        width: 450px;
        padding-top: 13px;
        padding-bottom: 13px;
        padding-left: 15px;
        padding-right: 15px;
        border-radius: 13px;
        background-color: #22272e;
      }
      .detail-title {
        color: #ffffff;
        font-size: 23px;
        font-weight: 700;
      }
      .detail-copy {
        color: #d4dbe4;
        font-size: 19px;
      }
      .reset {
        width: 450px;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 12px;
        border-width: 1px;
        border-color: #527cac;
        background-color: #294a6b;
      }
      .reset-text {
        color: #ffffff;
        font-size: 20px;
        font-weight: 700;
        text-align: center;
      }
    </style>
    <div class="card">
      <span class="title">Earth’s layers</span>
      <span class="subtitle">Press a layer or label • pinch to pull it out</span>

      <button class="layer" id="pick-crust">
        <div class="swatch crust-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Crust</span>
          <span class="layer-sub">5–70 km thick • solid</span>
        </div>
      </button>

      <button class="layer" id="pick-mantle">
        <div class="swatch mantle-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Mantle</span>
          <span class="layer-sub">Extends to 2,890 km deep</span>
        </div>
      </button>

      <button class="layer" id="pick-outer">
        <div class="swatch outer-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Outer core</span>
          <span class="layer-sub">2,890–5,150 km • liquid</span>
        </div>
      </button>

      <button class="layer" id="pick-inner">
        <div class="swatch inner-swatch"></div>
        <div class="layer-copy">
          <span class="layer-name">Inner core</span>
          <span class="layer-sub">5,150–6,371 km • solid</span>
        </div>
      </button>

      <div class="detail">
        <span class="detail-title" id="detail-title">Crust</span>
        <span class="detail-copy" id="detail-copy"></span>
      </div>
      <span class="subtitle">Layer thicknesses are exaggerated; model is not to scale.</span>
      <button class="reset" id="reset"><span class="reset-text">Reassemble Earth</span></button>
    </div>
  `, {
    width: 0.3,
    position: [0.24, 0.19, 0.02],
    rotationY: -0.2,
  });
  root.add(panel.object3D);

  const buttonIds = ['pick-crust', 'pick-mantle', 'pick-outer', 'pick-inner'];
  let selected = 0;

  function selectLayer(index) {
    selected = index;
    panel.set('detail-title', { text: layerData[index].name });
    panel.set('detail-copy', { text: layerData[index].fact });

    for (let i = 0; i < buttonIds.length; i++) {
      panel.set(buttonIds[i], {
        backgroundColor: i === index ? layerData[i].selectedBg : '#262b32',
        borderColor: i === index ? layerData[i].css : '#3a414b',
      });
    }
  }

  function resetLayers() {
    for (let i = 0; i < layers.length; i++) {
      layers[i].group.position.set(centerX, centerY, 0);
    }
  }

  for (let i = 0; i < layers.length; i++) {
    traits(layers[i].group, {
      grab: true,
      onPress: () => selectLayer(i),
    });
    panel.on(buttonIds[i], 'click', () => selectLayer(i));
  }

  panel.on('reset', 'click', resetLayers);
  traits(base, { onPress: resetLayers });
  selectLayer(0);

  return {
    root,
    update(time) {
      for (let i = 0; i < layers.length; i++) {
        const held = isGrabbed(layers[i].group);
        layers[i].material.emissiveIntensity = held
          ? 0.24
          : i === selected
            ? 0.14 + Math.sin(time * 3) * 0.045
            : 0.035;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const colors = {
    light: 0xffd34d,
    water: 0x37b9ff,
    carbon: 0xb7c2d0,
    oxygen: 0x55e6a5,
  };

  // Sun: press it to learn where the energy comes from.
  const sunGroup = new THREE.Group();
  sunGroup.name = 'Sun';
  sunGroup.position.set(-0.27, 0.365, -0.045);
  root.add(sunGroup);

  const sun = new THREE.Mesh(
    new THREE.SphereGeometry(0.052, 28, 16),
    new THREE.MeshStandardMaterial({
      color: 0xffd34d,
      emissive: 0xff9d18,
      emissiveIntensity: 0.85,
      roughness: 0.55,
    }),
  );
  sun.name = 'Sun';
  sunGroup.add(sun);

  const rayGeometry = new THREE.ConeGeometry(0.008, 0.025, 6);
  const rayMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd968,
    emissive: 0xffa71a,
    emissiveIntensity: 0.45,
  });
  for (let i = 0; i < 10; i += 1) {
    const angle = (i / 10) * Math.PI * 2;
    const ray = new THREE.Mesh(rayGeometry, rayMaterial);
    ray.position.set(Math.cos(angle) * 0.069, Math.sin(angle) * 0.069, 0);
    ray.rotation.z = angle - Math.PI / 2;
    sunGroup.add(ray);
  }

  // Pot, soil and plant.
  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.057, 0.043, 0.068, 28),
    new THREE.MeshStandardMaterial({ color: 0xb86842, roughness: 0.85 }),
  );
  pot.name = 'Plant pot';
  pot.position.set(-0.055, 0.04, 0);
  root.add(pot);

  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(0.062, 0.062, 0.015, 28),
    new THREE.MeshStandardMaterial({ color: 0xd58055, roughness: 0.8 }),
  );
  rim.position.set(-0.055, 0.077, 0);
  root.add(rim);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.055, 0.055, 0.006, 28),
    new THREE.MeshStandardMaterial({ color: 0x493326, roughness: 1 }),
  );
  soil.name = 'Soil and absorbed water';
  soil.position.set(-0.055, 0.087, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0045, 0.006, 0.172, 12),
    new THREE.MeshStandardMaterial({ color: 0x45934b, roughness: 0.75 }),
  );
  stem.name = 'Stem';
  stem.position.set(-0.055, 0.171, 0);
  root.add(stem);

  const leafGeometry = new THREE.SphereGeometry(1, 24, 12);
  const leafMaterial = new THREE.MeshStandardMaterial({
    color: 0x54ad55,
    roughness: 0.62,
  });

  function makeLeaf(name, x, y, z, angle, scaleX) {
    const leaf = new THREE.Mesh(leafGeometry, leafMaterial);
    leaf.name = name;
    leaf.position.set(x, y, z);
    leaf.scale.set(scaleX, 0.023, 0.008);
    leaf.rotation.z = angle;
    root.add(leaf);
    return leaf;
  }

  const leafLeft = makeLeaf('Leaf - lower left', -0.103, 0.163, 0.003, -0.42, 0.061);
  const leafRight = makeLeaf('Leaf - lower right', -0.008, 0.191, 0.006, 0.48, 0.062);
  const leafUpperLeft = makeLeaf('Leaf - upper left', -0.104, 0.239, 0, 0.5, 0.064);
  const leafUpperRight = makeLeaf('Leaf - upper right', -0.006, 0.271, -0.002, -0.38, 0.061);
  makeLeaf('Leaf - top', -0.054, 0.284, 0, Math.PI / 2, 0.047);

  // Arrows: light and carbon dioxide enter; water rises; oxygen exits.
  function makeArrow(name, start, end, color, radius) {
    const direction = new THREE.Vector3().subVectors(end, start);
    const length = direction.length();
    direction.normalize();

    const group = new THREE.Group();
    group.name = name;
    group.position.copy(start).add(end).multiplyScalar(0.5);
    group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction);

    const material = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 0.28,
      roughness: 0.45,
    });

    const headLength = Math.min(0.023, length * 0.3);
    const shaft = new THREE.Mesh(
      new THREE.CylinderGeometry(radius, radius, length - headLength, 10),
      material,
    );
    shaft.position.y = -headLength / 2;
    group.add(shaft);

    const head = new THREE.Mesh(
      new THREE.ConeGeometry(radius * 2.8, headLength, 12),
      material,
    );
    head.position.y = length / 2 - headLength / 2;
    group.add(head);

    root.add(group);
    return { group, start, end, material };
  }

  const lightArrow = makeArrow(
    'Light energy from the Sun',
    new THREE.Vector3(-0.228, 0.323, -0.026),
    new THREE.Vector3(-0.134, 0.264, -0.005),
    colors.light,
    0.0035,
  );
  const waterArrow = makeArrow(
    'Water absorbed by roots',
    new THREE.Vector3(-0.055, 0.074, 0.054),
    new THREE.Vector3(-0.055, 0.185, 0.054),
    colors.water,
    0.0032,
  );
  const carbonArrow = makeArrow(
    'Carbon dioxide entering leaf',
    new THREE.Vector3(0.087, 0.236, 0.012),
    new THREE.Vector3(0.015, 0.241, 0.012),
    colors.carbon,
    0.0032,
  );
  const oxygenArrow = makeArrow(
    'Oxygen leaving leaf',
    new THREE.Vector3(0.012, 0.292, 0.018),
    new THREE.Vector3(0.105, 0.354, 0.018),
    colors.oxygen,
    0.0035,
  );

  // Compact floating labels keep each arrow identifiable.
  function makeLabel(text, id, color, width, position) {
    const panel = ui(`
      <style>
        .tag { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
               border-radius: 14px; background-color: ${color}; justify-content: center; }
        .tag-text { color: #ffffff; font-size: 25px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag"><span class="tag-text" id="${id}">${text}</span></div>`,
      { width, position });
    root.add(panel.object3D);
    return panel;
  }

  makeLabel('Light', 'light-label', '#8c6816', 0.105, [-0.205, 0.255, 0.015]);
  makeLabel('Water', 'water-label', '#176b9c', 0.105, [-0.144, 0.116, 0.058]);
  makeLabel('Carbon dioxide', 'carbon-label', '#46515f', 0.16, [0.118, 0.206, 0.02]);
  makeLabel('Oxygen', 'oxygen-label', '#167555', 0.112, [0.13, 0.385, 0.022]);

  // Main explanation panel and controls.
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1b2026;
              border-width: 2px; border-color: #3a4651; }
      .title { color: #ffffff; font-size: 29px; font-weight: 700; }
      .formula { color: #b9f3c6; font-size: 21px; font-weight: 700; text-align: center; }
      .body { color: #e0e5eb; font-size: 22px; }
      .hint { color: #bac4cf; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; }
      .button { padding-top: 10px; padding-bottom: 10px; padding-left: 13px; padding-right: 13px;
                border-radius: 12px; background-color: #287c50; }
      .button-alt { padding-top: 10px; padding-bottom: 10px; padding-left: 13px; padding-right: 13px;
                    border-radius: 12px; background-color: #3c4a59; }
      .button-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="formula">6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂</span>
      <span class="body" id="explanation">Leaves use light energy to turn water and carbon dioxide into glucose, releasing oxygen.</span>
      <span class="hint">Press the Sun, plant, or arrows.</span>
      <div class="row">
        <button class="button" id="flow"><span class="button-text" id="flow-text">Pause flow</span></button>
        <button class="button-alt" id="next"><span class="button-text">Next step</span></button>
      </div>
    </div>`,
    { width: 0.255, position: [0.255, 0.125, 0.09], rotationY: -0.24 });
  root.add(info.object3D);

  const steps = [
    '1. Chlorophyll in chloroplasts captures energy from sunlight.',
    '2. Roots absorb water; the stem transports it to the leaves.',
    '3. Leaves take in carbon dioxide through pores called stomata.',
    '4. Light-dependent reactions make ATP and NADPH and split water, releasing oxygen.',
    '5. The Calvin cycle uses ATP and NADPH to fix carbon dioxide into sugars.',
    '6. Glucose stores chemical energy and helps the plant grow; oxygen exits the leaf.',
  ];
  let stepIndex = -1;
  let flowing = true;

  info.on('next', 'click', () => {
    stepIndex = (stepIndex + 1) % steps.length;
    info.set('explanation', { text: steps[stepIndex] });
  });
  info.on('flow', 'click', () => {
    flowing = !flowing;
    info.set('flow-text', { text: flowing ? 'Pause flow' : 'Resume flow' });
  });

  function explain(text) {
    info.set('explanation', { text });
  }

  traits(sunGroup, {
    onPress: () => explain('Sunlight supplies energy. Chlorophyll absorbs mainly red and blue light and reflects green light.'),
  });
  traits(soil, {
    onPress: () => explain('Roots absorb water from soil. Xylem carries water and dissolved minerals upward to the leaves.'),
  });
  traits(stem, {
    grab: true,
    onPress: () => explain('The stem supports the leaves. Xylem brings water up; phloem distributes sugars made by photosynthesis.'),
  });

  traits(leafUpperRight, {
    onPress: () => explain('Inside leaf cells, chloroplasts contain chlorophyll. Their thylakoid membranes host the light-dependent reactions.'),
  });
  traits(lightArrow.group, {
    onPress: () => explain('LIGHT INPUT: light energy drives electron transfer into the photosynthetic electron transport chain, forming ATP and NADPH.'),
  });
  traits(waterArrow.group, {
    onPress: () => explain('WATER INPUT: H₂O is split in the light reactions. Its electrons replenish chlorophyll and oxygen is released.'),
  });
  traits(carbonArrow.group, {
    onPress: () => explain('CARBON DIOXIDE INPUT: CO₂ enters through stomata and is fixed by Rubisco during the Calvin cycle.'),
  });
  traits(oxygenArrow.group, {
    onPress: () => explain('OXYGEN OUTPUT: O₂ comes from splitting water, not from carbon dioxide. It diffuses out through stomata.'),
  });

  // Reusable moving beads show direction without making any grabbable object move.
  const beadGeometry = new THREE.SphereGeometry(0.005, 10, 6);
  const beadMaterials = {};
  const beads = [];
  const arrows = [lightArrow, waterArrow, carbonArrow, oxygenArrow];
  const keys = ['light', 'water', 'carbon', 'oxygen'];

  for (let i = 0; i < arrows.length; i += 1) {
    const colorKey = keys[i];
    beadMaterials[colorKey] = new THREE.MeshBasicMaterial({ color: colors[colorKey] });
    for (let j = 0; j < 2; j += 1) {
      const bead = new THREE.Mesh(beadGeometry, beadMaterials[colorKey]);
      root.add(bead);
      const phase = j * 0.5 + i * 0.13;
      bead.position.lerpVectors(arrows[i].start, arrows[i].end, phase % 1);
      beads.push({ mesh: bead, arrow: arrows[i], phase });
    }
  }

  const tempPosition = new THREE.Vector3();
  let flowTime = 0;

  return {
    root,
    update(time, delta) {
      if (flowing) flowTime += delta;

      for (let i = 0; i < beads.length; i += 1) {
        const bead = beads[i];
        const t = (flowTime * 0.55 + bead.phase) % 1;
        tempPosition.lerpVectors(bead.arrow.start, bead.arrow.end, t);
        bead.mesh.position.copy(tempPosition);
      }

      // Gentle visual emphasis only; the grabbable stem remains stationary.
      const pulse = 1 + Math.sin(time * 2.1) * 0.025;
      sun.scale.setScalar(pulse);

      lightArrow.material.emissiveIntensity = 0.24 + Math.sin(time * 3) * 0.08;
      waterArrow.material.emissiveIntensity = 0.24 + Math.sin(time * 3 + 1.5) * 0.08;
      carbonArrow.material.emissiveIntensity = 0.22 + Math.sin(time * 3 + 3) * 0.07;
      oxygenArrow.material.emissiveIntensity = 0.26 + Math.sin(time * 3 + 4.5) * 0.09;

      leafMaterial.emissive.setHex(0x173d19);
      leafMaterial.emissiveIntensity = 0.12 + Math.sin(time * 1.6) * 0.04;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const RADIUS = 0.15;
  const HOME_X = -0.135;
  const HOME_Y = 0.23;
  const TILT_X = -0.08;
  const TILT_Y = -0.3;
  const layers = [];

  function createLayer(key, label, color, innerRadius, outerRadius, fact, baseGlow) {
    const group = new THREE.Group();
    group.name = label;
    group.position.set(HOME_X, HOME_Y, 0);
    group.rotation.set(TILT_X, TILT_Y, 0);

    const geometry = innerRadius === 0
      ? new THREE.CircleGeometry(outerRadius, 64)
      : new THREE.RingGeometry(innerRadius, outerRadius, 64, 1);

    const faceMaterial = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: baseGlow,
      roughness: 0.48,
      metalness: key === 'inner' || key === 'outer' ? 0.16 : 0.03,
      side: THREE.DoubleSide,
    });

    const face = new THREE.Mesh(geometry, faceMaterial);
    face.name = label + ' cut-away face';
    face.position.z = 0.003;
    group.add(face);
    root.add(group);

    const layer = { key, label, color, fact, group, face, faceMaterial, baseGlow };
    layers.push(layer);
    return layer;
  }

  const crust = createLayer(
    'crust',
    'Crust',
    0xb49a68,
    0.142,
    RADIUS,
    'A thin, solid, rocky shell. Oceanic crust is mostly basalt; continental crust is richer in granite.',
    0
  );

