    'A solid ball of mostly iron and nickel. It is extremely hot, but immense pressure keeps it solid.',
    0.18
  );

  // The exterior is the back half of the sphere; the colored disks form its cut face.
  const exterior = new THREE.Mesh(
    new THREE.SphereGeometry(RADIUS, 48, 24, Math.PI, Math.PI),
    new THREE.MeshStandardMaterial({
      color: 0x287eae,
      roughness: 0.58,
      metalness: 0.04,
    })
  );
  exterior.name = 'Earth outer surface';
  crust.group.add(exterior);

  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(RADIUS - 0.001, 0.0022, 8, 64),
    crust.faceMaterial
  );
  rim.name = 'Crust rim';
  rim.position.z = 0.001;
  crust.group.add(rim);

  const info = ui(`
    <style>
      .card {
        width: 520px;
        flex-direction: column;
        gap: 8px;
        padding-top: 18px;
        padding-bottom: 18px;
        padding-left: 18px;
        padding-right: 18px;
        border-radius: 18px;
        border-width: 1px;
        border-color: #3a424e;
        background-color: #1d2127;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
      }
      .instruction {
        color: #bdc7d3;
        font-size: 20px;
      }
      .layer {
        width: 472px;
        flex-direction: row;
        align-items: center;
        gap: 12px;
        padding-top: 8px;
        padding-bottom: 8px;
        padding-left: 12px;
        padding-right: 12px;
        border-radius: 12px;
        border-width: 1px;
        border-color: #3a424d;
