      </button>
      <span class="note">Cut-face radii are approximate; the crust is enlarged for visibility.</span>
    </div>
  `, {
    width: 0.35,
    position: [0.235, 0.225, 0.015],
    rotationY: -0.18,
  });
  root.add(info.object3D);

  let selectedKey = 'crust';

  function selectLayer(key) {
    const layer = layers.find(item => item.key === key) || layers[0];
    selectedKey = layer.key;
    info.set('detail-title', { text: layer.label });
    info.set('detail-body', { text: layer.fact });

    for (let i = 0; i < layers.length; i++) {
      info.set('layer-' + layers[i].key, {
        backgroundColor: layers[i].key === selectedKey ? '#3b4755' : '#292e36',
      });
    }
  }

  for (let i = 0; i < layers.length; i++) {
    const layer = layers[i];
    traits(layer.group, {
      grab: true,
      onPress: () => selectLayer(layer.key),
    });
    info.on('layer-' + layer.key, 'click', () => selectLayer(layer.key));
  }

  info.on('reset', 'click', () => {
    for (let i = 0; i < layers.length; i++) {
      const group = layers[i].group;
      group.position.set(HOME_X, HOME_Y, 0);
      group.rotation.set(TILT_X, TILT_Y, 0);
    }
  });

  selectLayer('crust');

  return {
    root,
    update(time) {
      const pulse = 0.42 + Math.sin(time * 3) * 0.12;
      for (let i = 0; i < layers.length; i++) {
        const layer = layers[i];
        layer.faceMaterial.emissiveIntensity =
          layer.key === selectedKey ? pulse : layer.baseGlow;
      }
    },
  };
}

