    panel.set('detailTitle', { text: city.name + ' · ' + city.condition });
    panel.set('detailBody', {
      text: 'Feels like ' + temperature(city.feels) +
        ' · Humidity ' + city.humidity + '% · Wind ' + city.wind,
    });
