  });

  selectCity(0);

  return {
    root,
    update(time, delta) {
      tokyoRays.rotation.z = time * 0.18;
      newYorkRays.rotation.z = -time * 0.12;

      for (let i = 0; i < rainDrops.length; i++) {
        const drop = rainDrops[i];
        drop.mesh.position.y = -0.024 - ((time * 0.03 + drop.phase) % 0.032);
      }

      const blend = Math.min(1, delta * 8);
      for (let i = 0; i < icons.length; i++) {
        const targetScale = i === selected ? 1.07 : 1;
        const scale = icons[i].scale.x + (targetScale - icons[i].scale.x) * blend;
        icons[i].scale.setScalar(scale);
      }
    },
  };
}

