    const shaftLength = length - headLength;
    const shaft = new THREE.Mesh(unitCylinder, material);
    shaft.scale.set(0.0065, shaftLength, 0.0065);
    shaft.position.y = shaftLength / 2;
    group.add(shaft);

    const head = new THREE.Mesh(unitCone, material);
    head.scale.set(0.017, headLength, 0.017);
    head.position.y = shaftLength + headLength / 2;
    group.add(head);

    // A larger invisible target makes the whole arrow easy to poke or pinch.
    const hit = new THREE.Mesh(unitCylinder, hitMaterial);
    hit.scale.set(0.022, length, 0.022);
    hit.position.y = length / 2;
    group.add(hit);

    const particles = [];
    for (let i = 0; i < 3; i++) {
      const particle = new THREE.Mesh(particleGeometry, material);
      particle.position.y = (i + 0.5) * length / 3;
      group.add(particle);
      particles.push(particle);
    }

    root.add(group);
    traits(group, { onPress: () => select(key) });
    arrows.push({ key, group, material, particles, length });
    return group;
  }

  makeArrow(
    'light',
    'Light energy arrow',
    [-0.225, 0.320, -0.025],
    [-0.085, 0.239, 0.005],
    0xffcf4a,
  );
  makeArrow(
    'water',
    'Water arrow',
    [-0.275, 0.025, 0.045],
    [-0.073, 0.087, 0.024],
    0x38a9ed,
  );
  makeArrow(
    'co2',
    'Carbon dioxide arrow',
    [0.300, 0.207, 0.030],
    [0.050, 0.186, 0.010],
    0xafbccc,
  );
  makeArrow(
    'oxygen',
    'Oxygen arrow',
    [0.058, 0.255, 0.008],
    [0.292, 0.374, 0.024],
    0x52d9c8,
  );

  function makeTag(key, label, position, width, cssColor) {
    const tag = ui(`
      <style>
        .tag { display: flex; width: 360px; }
        .tagButton { display: flex; align-items: center; justify-content: center;
                     padding-top: 9px; padding-bottom: 9px; padding-left: 14px; padding-right: 14px;
                     border-radius: 14px; border-width: 3px; border-color: ${cssColor};
                     background-color: #20262c; }
        .tagText { color: ${cssColor}; font-size: 25px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag">
        <button class="tagButton" id="tag"><span class="tagText">${label}</span></button>
      </div>`, { width, position });
    tag.object3D.name = label + ' label';
    root.add(tag.object3D);
    tag.on('tag', 'click', () => select(key));
  }

  makeTag('light', 'Light energy', [-0.220, 0.225, 0.085], 0.160, '#ffe078');
  makeTag('water', 'Water (H₂O)', [-0.215, 0.105, 0.090], 0.165, '#79cfff');
  makeTag('co2', 'Carbon dioxide (CO₂)', [0.260, 0.158, 0.080], 0.180, '#d2d9e4');
  makeTag('oxygen', 'Oxygen (O₂)', [0.265, 0.416, 0.090], 0.160, '#83f0df');

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      if (flowRunning) flowTime += dt;

      rays.rotation.z = time * 0.035;
      sunMaterial.emissiveIntensity = 0.95 + Math.sin(time * 1.4) * 0.12;
      leafMaterial.emissiveIntensity = activeKey === 'leaf'
        ? 0.55 + Math.sin(time * 3) * 0.15
        : 0.16;

      for (let i = 0; i < leaves.length; i++) {
        const leaf = leaves[i];
        leaf.mesh.rotation.z = leaf.baseRotation + Math.sin(time * 0.9 + leaf.phase) * 0.025;
      }

      for (let i = 0; i < arrows.length; i++) {
        const arrow = arrows[i];
        const selected = activeKey === arrow.key;
        arrow.material.emissiveIntensity = selected
          ? 0.85 + Math.sin(time * 3.2) * 0.18
          : 0.28 + Math.sin(flowTime * 2 + i) * 0.06;

        for (let j = 0; j < arrow.particles.length; j++) {
          const phase = (flowTime * 0.22 + j / 3) % 1;
          arrow.particles[j].position.y = 0.010 + phase * (arrow.length - 0.020);
        }
      }
    },
  };
}

