    { expression: '12 × 4', answer: 48, options: [44, 48, 52, 56] },
    { expression: '7 × 5', answer: 35, options: [30, 32, 35, 42] },
    { expression: '11 × 6', answer: 66, options: [60, 61, 66, 72] },
  ];

  const panel = ui(`
    <style>
      .card {
        flex-direction: column;
        gap: 14px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 24px;
        padding-right: 24px;
