        flex-direction: row;
        justify-content: space-between;
        align-items: center;
      }
      .label { color: #aeb8c7; font-size: 20px; font-weight: 700; }
      .score { color: #ffd166; font-size: 22px; font-weight: 700; }
      .question {
        color: #ffffff;
        font-size: 48px;
        font-weight: 700;
        text-align: center;
      }
      .prompt { color: #d7dbe2; font-size: 21px; text-align: center; }
      .answers { flex-direction: row; gap: 12px; }
      .answer {
        width: 118px;
        height: 70px;
        justify-content: center;
        align-items: center;
        border-radius: 14px;
        background-color: #315fbd;
        border-color: #71a0ff;
        border-width: 2px;
      }
      .answer-text { color: #ffffff; font-size: 28px; font-weight: 700; }
