      .next {
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 24px;
        padding-right: 24px;
        border-radius: 12px;
        background-color: #2f855a;
      }
      .next-text { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="header">
        <span class="label" id="progress">Question 1 of 5</span>
        <span class="score" id="score">Score: 0 / 5</span>
      </div>
      <span class="question" id="question">6 × 7 = ?</span>
      <span class="prompt">Choose an answer</span>
      <div class="answers">
        <button class="answer" id="answer0"><span class="answer-text" id="answerText0">36</span></button>
        <button class="answer" id="answer1"><span class="answer-text" id="answerText1">42</span></button>
        <button class="answer" id="answer2"><span class="answer-text" id="answerText2">48</span></button>
        <button class="answer" id="answer3"><span class="answer-text" id="answerText3">54</span></button>
      </div>
      <span class="feedback" id="feedback">Tap an answer to begin.</span>
      <div class="actions">
        <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
      </div>
    </div>`, {
    width: 0.48,
    position: [0, 0.21, 0.04],
  });
  root.add(panel.object3D);

  // Five physical score lights sit above the quiz panel.
  const lightGeometry = new THREE.SphereGeometry(0.016, 24, 12);
  const scoreLights = [];
  for (let i = 0; i < 5; i++) {
    const light = new THREE.Mesh(
      lightGeometry,
      new THREE.MeshStandardMaterial({
        color: 0x48505c,
        emissive: 0x11151b,
        emissiveIntensity: 0.25,
        roughness: 0.45,
      }),
    );
    light.name = `ScoreLight${i + 1}`;
    light.position.set((i - 2) * 0.05, 0.455, -0.06);
    root.add(light);
    scoreLights.push(light);
  }

  let current = 0;
  let score = 0;
  let answered = false;
  let complete = false;
  let celebrationTime = 0;

  function setScoreLight(index, correct) {
    const material = scoreLights[index].material;
    material.color.setHex(correct ? 0x4ade80 : 0xff6b6b);
    material.emissive.setHex(correct ? 0x15803d : 0x991b1b);
    material.emissiveIntensity = 0.9;
  }

  function resetLights() {
    scoreLights.forEach((light) => {
      light.material.color.setHex(0x48505c);
      light.material.emissive.setHex(0x11151b);
      light.material.emissiveIntensity = 0.25;
      light.scale.setScalar(1);
    });
  }

  function showQuestion() {
    const item = questions[current];
    answered = false;
    complete = false;
    panel.set('progress', { text: `Question ${current + 1} of 5` });
    panel.set('question', { text: `${item.expression} = ?`, color: '#ffffff' });
    panel.set('feedback', {
      text: current === 0 ? 'Tap an answer to begin.' : 'Choose the correct product.',
      color: '#d7dbe2',
    });
    panel.set('nextText', { text: current === 4 ? 'See result' : 'Next question' });

    item.options.forEach((option, index) => {
      panel.set(`answerText${index}`, { text: String(option) });
      panel.set(`answer${index}`, {
        backgroundColor: '#315fbd',
        display: 'flex',
      });
    });
  }

  function finishQuiz() {
    complete = true;
    celebrationTime = 0;
    panel.set('progress', { text: 'Quiz complete!' });
    panel.set('question', { text: `${score} / 5`, color: '#ffd166' });
    const message = score === 5
      ? 'Perfect score! Multiplication master!'
      : score >= 3
        ? 'Great work! Keep practicing.'
        : 'Good effort! Try again to improve.';
    panel.set('feedback', { text: message, color: '#ffffff' });
    for (let i = 0; i < 4; i++) {
      panel.set(`answer${i}`, { display: 'none' });
    }
    panel.set('nextText', { text: 'Play again' });
  }

  for (let index = 0; index < 4; index++) {
    panel.on(`answer${index}`, 'click', () => {
      if (answered || complete) return;
      answered = true;

      const item = questions[current];
      const selected = item.options[index];
      const correct = selected === item.answer;
      const correctIndex = item.options.indexOf(item.answer);

      if (correct) {
        score++;
        panel.set('feedback', { text: 'Correct! Well done.', color: '#4ade80' });
        panel.set(`answer${index}`, { backgroundColor: '#237a4b' });
      } else {
        panel.set('feedback', {
          text: `Not quite. ${item.expression} = ${item.answer}.`,
          color: '#ff9a9a',
        });
        panel.set(`answer${index}`, { backgroundColor: '#a83d46' });
        panel.set(`answer${correctIndex}`, { backgroundColor: '#237a4b' });
      }

      panel.set('score', { text: `Score: ${score} / 5` });
      setScoreLight(current, correct);
    });
  }

  panel.on('next', 'click', () => {
    if (complete) {
      current = 0;
      score = 0;
      resetLights();
      panel.set('score', { text: 'Score: 0 / 5' });
      showQuestion();
      return;
    }

    if (!answered) {
      panel.set('feedback', {
        text: 'Choose an answer before continuing.',
        color: '#ffd166',
      });
      return;
    }

    if (current === questions.length - 1) {
      finishQuiz();
    } else {
      current++;
      showQuestion();
    }
  });

  return {
    root,
    update(time, delta) {
      if (complete) {
        celebrationTime += delta;
        for (let i = 0; i < score; i++) {
          const pulse = 1 + Math.sin(celebrationTime * 5 + i * 0.7) * 0.12;
          scoreLights[i].scale.setScalar(pulse);
        }
      }
    },
  };
}

