      .note { color: #95a5b4; font-size: 20px; text-align: center; }
    </style>
    <div class="dashboard">
      <div class="header">
        <div class="heading">
          <span class="title">Weather dashboard</span>
          <span class="subtitle">Select a city · sample conditions</span>
        </div>
        <button class="unit-button" id="units">
          <span class="unit-text" id="unit-label">Show °F</span>
        </button>
      </div>
      <div class="city-row">
        <button class="city" id="tokyo">
          <span class="city-name">Tokyo</span>
          <span class="temperature" id="tokyo-temp">24°C</span>
          <span class="condition">Sunny</span>
        </button>
        <button class="city" id="london">
          <span class="city-name">London</span>
          <span class="temperature" id="london-temp">12°C</span>
          <span class="condition">Rain</span>
        </button>
        <button class="city" id="newyork">
          <span class="city-name">New York</span>
          <span class="temperature" id="newyork-temp">18°C</span>
          <span class="condition">Cloudy</span>
        </button>
      </div>
      <div class="footer">
        <span class="detail" id="detail">Tokyo · Sunny · High 27°C / Low 18°C</span>
        <span class="note">Demo data · not live</span>
      </div>
    </div>
  `, { width: 0.64, position: [0, 0.18, 0.11] });
  root.add(panel.object3D);

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.6, 0.024, 0.2),
    new THREE.MeshStandardMaterial({ color: 0x20262d, roughness: 0.72, metalness: 0.15 }),
  );
  base.name = 'Dashboard base';
  base.position.set(0, 0.012, 0.025);
  root.add(base);

  const stationY = 0.419;
  const stationX = [-0.192, 0, 0.192];
  const discGeometry = new THREE.CylinderGeometry(0.066, 0.066, 0.012, 32);
  const ringGeometry = new THREE.TorusGeometry(0.069, 0.0035, 8, 40);
  const discMaterial = new THREE.MeshStandardMaterial({
    color: 0x27333e,
    roughness: 0.55,
    metalness: 0.25,
  });
  const selectedRingMaterial = new THREE.MeshStandardMaterial({
    color: 0x78ddff,
    emissive: 0x2599c2,
    emissiveIntensity: 0.7,
    roughness: 0.35,
  });
  const ringMaterial = new THREE.MeshStandardMaterial({
    color: 0x526675,
    roughness: 0.5,
    metalness: 0.25,
  });

  const rings = [];
  const iconGroups = [];

  for (let i = 0; i < cities.length; i++) {
    const disc = new THREE.Mesh(discGeometry, discMaterial);
    disc.name = `${cities[i].name} weather button`;
    disc.position.set(stationX[i], stationY, 0);
    disc.rotation.x = Math.PI / 2;
    root.add(disc);
    traits(disc, { onPress: () => selectCity(i) });

    const ring = new THREE.Mesh(ringGeometry, ringMaterial);
    ring.name = `${cities[i].name} selection ring`;
    ring.position.set(stationX[i], stationY, 0.009);
    root.add(ring);
    rings.push(ring);

    const icon = new THREE.Group();
    icon.position.set(stationX[i], stationY, 0.025);
    root.add(icon);
    iconGroups.push(icon);
  }

  // Tokyo: a rotating sun with instanced rays.
  const tokyoIcon = iconGroups[0];
  tokyoIcon.name = 'Tokyo sunny icon';

  const sunMaterial = new THREE.MeshStandardMaterial({
    color: 0xffc74d,
    emissive: 0xff9d22,
    emissiveIntensity: 0.65,
    roughness: 0.45,
  });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.028, 24, 12), sunMaterial);
  sun.name = 'Tokyo sun';
  tokyoIcon.add(sun);

  const rayGeometry = new THREE.CylinderGeometry(0.0028, 0.0028, 0.018, 6);
  const rays = new THREE.InstancedMesh(rayGeometry, sunMaterial, 8);
  rays.name = 'Sun rays';
  const rayTransform = new THREE.Object3D();
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    rayTransform.position.set(Math.cos(angle) * 0.047, Math.sin(angle) * 0.047, 0);
    rayTransform.rotation.set(0, 0, angle - Math.PI / 2);
    rayTransform.updateMatrix();
    rays.setMatrixAt(i, rayTransform.matrix);
  }
  rays.instanceMatrix.needsUpdate = true;
  tokyoIcon.add(rays);

  const cloudGeometry = new THREE.SphereGeometry(0.025, 24, 12);
  const londonCloudMaterial = new THREE.MeshStandardMaterial({
    color: 0xaebbc8,
    roughness: 0.85,
  });
  const newYorkCloudMaterial = new THREE.MeshStandardMaterial({
    color: 0xe0e7ed,
    roughness: 0.85,
  });

  function addCloudPuff(parent, x, y, scale, material, name) {
    const puff = new THREE.Mesh(cloudGeometry, material);
    puff.name = name;
    puff.position.set(x, y, 0);
    puff.scale.set(scale, scale * 0.82, scale * 0.48);
    parent.add(puff);
    return puff;
  }

  // London: a rain cloud with falling drops.
  const londonIcon = iconGroups[1];
  londonIcon.name = 'London rain icon';
  addCloudPuff(londonIcon, -0.028, 0.005, 1.1, londonCloudMaterial, 'London cloud left');
  addCloudPuff(londonIcon, 0, 0.019, 1.35, londonCloudMaterial, 'London cloud top');
  addCloudPuff(londonIcon, 0.03, 0.005, 1, londonCloudMaterial, 'London cloud right');

  const rainMaterial = new THREE.MeshStandardMaterial({
    color: 0x58bfff,
    emissive: 0x16689c,
    emissiveIntensity: 0.35,
    roughness: 0.4,
  });
  const dropGeometry = new THREE.ConeGeometry(0.0045, 0.014, 8);
  const rainDrops = [];
  const dropX = [-0.026, 0, 0.026];
  for (let i = 0; i < 3; i++) {
    const drop = new THREE.Mesh(dropGeometry, rainMaterial);
    drop.name = `Rain drop ${i + 1}`;
    drop.position.set(dropX[i], -0.02 - i * 0.012, 0.008);
    drop.rotation.z = Math.PI;
    londonIcon.add(drop);
    rainDrops.push(drop);
  }

  // New York: a broad, gently drifting cloud.
  const newYorkIcon = iconGroups[2];
  newYorkIcon.name = 'New York cloudy icon';
  addCloudPuff(newYorkIcon, -0.03, -0.002, 1.15, newYorkCloudMaterial, 'New York cloud left');
  addCloudPuff(newYorkIcon, -0.008, 0.018, 1.25, newYorkCloudMaterial, 'New York cloud top');
  addCloudPuff(newYorkIcon, 0.024, 0.008, 1.25, newYorkCloudMaterial, 'New York cloud center');
  addCloudPuff(newYorkIcon, 0.043, -0.006, 0.85, newYorkCloudMaterial, 'New York cloud right');

  function formatTemperature(celsius) {
    const value = fahrenheit ? celsius * 9 / 5 + 32 : celsius;
    return `${Math.round(value)}°${fahrenheit ? 'F' : 'C'}`;
  }

  function renderTemperatures() {
    for (const city of cities) {
      panel.set(`${city.id}-temp`, { text: formatTemperature(city.temp) });
    }
    const selected = cities[selectedIndex];
    panel.set('detail', {
      text: `${selected.name} · ${selected.condition} · High ${formatTemperature(selected.high)} / Low ${formatTemperature(selected.low)}`,
    });
    panel.set('unit-label', { text: fahrenheit ? 'Show °C' : 'Show °F' });
  }

  function selectCity(index) {
    selectedIndex = index;
    for (let i = 0; i < cities.length; i++) {
      const selected = i === selectedIndex;
      rings[i].material = selected ? selectedRingMaterial : ringMaterial;
      panel.set(cities[i].id, {
        backgroundColor: selected ? '#314b60' : '#242a33',
      });
    }
    renderTemperatures();
  }

  for (let i = 0; i < cities.length; i++) {
    panel.on(cities[i].id, 'click', () => selectCity(i));
  }

  panel.on('units', 'click', () => {
    fahrenheit = !fahrenheit;
    renderTemperatures();
  });

  selectCity(0);

  return {
    root,
    update(time) {
      tokyoIcon.rotation.z = time * 0.12;

      londonIcon.position.y = stationY + Math.sin(time * 1.3) * 0.003;
      newYorkIcon.position.y = stationY + Math.sin(time * 1.1 + 1) * 0.003;
      newYorkIcon.rotation.z = Math.sin(time * 0.7) * 0.018;

      for (let i = 0; i < rainDrops.length; i++) {
        const phase = (time * 0.38 + i * 0.29) % 1;
        rainDrops[i].position.y = -0.016 - phase * 0.04;
      }

      for (let i = 0; i < rings.length; i++) {
        const scale = i === selectedIndex ? 1 + Math.sin(time * 2.8) * 0.025 : 1;
        rings[i].scale.setScalar(scale);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const habits = [
    { name: 'Drink water', color: '#167d96', checked: new Array(7).fill(false) },
    { name: 'Move 20 min', color: '#347a4c', checked: new Array(7).fill(false) },
    { name: 'Read 10 min', color: '#795193', checked: new Array(7).fill(false) },
  ];
  let totalChecks = 0;

  const headerCells = days.map((day) =>
    `<span class="day-heading">${day}</span>`
  ).join('');

  const habitRows = habits.map((habit, habitIndex) => {
    const cells = days.map((day, dayIndex) => `
      <button class="day-button" id="cell-${habitIndex}-${dayIndex}">
        <span class="day-mark" id="mark-${habitIndex}-${dayIndex}">·</span>
      </button>`
    ).join('');

    return `
      <div class="habit-row">
        <span class="habit-name">${habit.name}</span>
        ${cells}
        <span class="streak" id="streak-${habitIndex}">0 days</span>
      </div>`;
  }).join('');

  const panel = ui(`
    <style>
      .panel {
        display: flex;
        flex-direction: column;
        gap: 11px;
        width: 580px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 20px;
        padding-right: 20px;
        border-radius: 22px;
        border-width: 1px;
        border-color: #3b434e;
        background-color: #1a1d22;
      }
      .top {
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
      }
      .total {
        color: #8fd8c0;
        font-size: 20px;
        font-weight: 700;
      }
      .hint {
        color: #b5bec9;
        font-size: 19px;
      }
      .habit-row {
        display: flex;
        flex-direction: row;
        align-items: center;
        gap: 6px;
      }
      .habit-name {
        width: 116px;
        margin-right: 6px;
        color: #edf1f5;
        font-size: 20px;
        font-weight: 700;
      }
      .row-label {
        width: 116px;
        margin-right: 6px;
        color: #8f9aa8;
        font-size: 17px;
      }
      .day-heading {
        width: 42px;
        height: 24px;
        text-align: center;
        color: #9faab7;
        font-size: 16px;
        font-weight: 700;
      }
      .streak-heading {
        width: 64px;
        margin-left: 6px;
        text-align: right;
        color: #9faab7;
        font-size: 17px;
        font-weight: 700;
      }
      .day-button {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 42px;
        height: 44px;
        padding-top: 0px;
        padding-bottom: 0px;
        padding-left: 0px;
        padding-right: 0px;
        border-radius: 10px;
        border-width: 1px;
        border-color: #4a5563;
        background-color: #303843;
      }
      .day-mark {
        color: #818c99;
        font-size: 25px;
        font-weight: 700;
        text-align: center;
      }
      .streak {
        width: 64px;
        margin-left: 6px;
        text-align: right;
        color: #ffffff;
        font-size: 19px;
        font-weight: 700;
      }
      .footer {
        color: #8f9aa8;
        font-size: 17px;
      }
    </style>
    <div class="panel">
      <div class="top">
        <span class="title">This week's habits</span>
        <span class="total" id="total">0 / 21 done</span>
      </div>
      <span class="hint">Tap a day to check it off. Tap again to undo.</span>
      <div class="habit-row">
        <span class="row-label">Habit</span>
        ${headerCells}
        <span class="streak-heading">Streak</span>
      </div>
      ${habitRows}
      <span class="footer">Streak = consecutive days through your latest checked day.</span>
    </div>
  `, {
    width: 0.48,
    position: [0, 0.23, 0],
  });

  root.add(panel.object3D);

  function getStreak(checked) {
    let cursor = checked.length - 1;

    while (cursor >= 0 && !checked[cursor]) cursor--;
    if (cursor < 0) return 0;

    let streak = 0;
    while (cursor >= 0 && checked[cursor]) {
      streak++;
      cursor--;
    }
    return streak;
  }

  function renderHabit(habitIndex) {
    const habit = habits[habitIndex];

    for (let dayIndex = 0; dayIndex < 7; dayIndex++) {
      const checked = habit.checked[dayIndex];
      panel.set(`cell-${habitIndex}-${dayIndex}`, {
        backgroundColor: checked ? habit.color : '#303843',
      });
      panel.set(`mark-${habitIndex}-${dayIndex}`, {
        text: checked ? '✓' : '·',
        color: checked ? '#ffffff' : '#818c99',
      });
    }

    const streak = getStreak(habit.checked);
    panel.set(`streak-${habitIndex}`, {
      text: streak === 1 ? '1 day' : `${streak} days`,
      color: streak > 0 ? '#8fd8c0' : '#ffffff',
    });
    panel.set('total', { text: `${totalChecks} / 21 done` });
  }

  habits.forEach((habit, habitIndex) => {
    for (let dayIndex = 0; dayIndex < 7; dayIndex++) {
      panel.on(`cell-${habitIndex}-${dayIndex}`, 'click', () => {
        habit.checked[dayIndex] = !habit.checked[dayIndex];
        totalChecks += habit.checked[dayIndex] ? 1 : -1;
        renderHabit(habitIndex);
      });
    }
  });

  return { root };
}

export default function build({ THREE, ui }) {
  const root = new THREE.Group();

  const questions = [
    { a: 6, b: 7, choices: [36, 42, 48, 54], answer: 42 },
    { a: 8, b: 9, choices: [72, 69, 64, 81], answer: 72 },
    { a: 12, b: 4, choices: [44, 52, 46, 48], answer: 48 },
    { a: 15, b: 6, choices: [80, 75, 90, 96], answer: 90 },
    { a: 13, b: 7, choices: [84, 91, 97, 98], answer: 91 },
  ];

  const panel = ui(`
    <style>
      .card {
        width: 540px;
        height: 500px;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 20px;
        background-color: #1a1d22;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
        text-align: center;
      }
      .meta {
        width: 496px;
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
      }
      .meta-text {
        color: #b9c5d6;
        font-size: 21px;
        font-weight: 700;
      }
      .question {
        color: #ffffff;
        font-size: 32px;
        font-weight: 700;
        text-align: center;
        padding-top: 5px;
        padding-bottom: 5px;
      }
      .answers {
        width: 496px;
        flex-direction: column;
        gap: 9px;
      }
      .answer {
        width: 496px;
        height: 49px;
        align-items: center;
        justify-content: center;
        border-width: 0px;
        border-radius: 12px;
        background-color: #303744;
      }
      .answer-text {
        color: #ffffff;
        font-size: 25px;
        font-weight: 700;
      }
      .feedback {
        color: #c7cfda;
        font-size: 20px;
        text-align: center;
      }
      .next {
        width: 496px;
        height: 47px;
        align-items: center;
        justify-content: center;
        border-width: 0px;
        border-radius: 12px;
        background-color: #2f6fdb;
      }
      .next-text {
        color: #ffffff;
        font-size: 22px;
        font-weight: 700;
      }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <div class="meta">
        <span class="meta-text" id="progress">Question 1 of 5</span>
        <span class="meta-text" id="score">Score: 0 / 5</span>
      </div>
      <span class="question" id="question">6 × 7 = ?</span>
      <div class="answers">
        <button class="answer" id="a0"><span class="answer-text" id="a0text">36</span></button>
        <button class="answer" id="a1"><span class="answer-text" id="a1text">42</span></button>
        <button class="answer" id="a2"><span class="answer-text" id="a2text">48</span></button>
        <button class="answer" id="a3"><span class="answer-text" id="a3text">54</span></button>
      </div>
      <span class="feedback" id="feedback">Pinch or poke the correct product.</span>
      <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
    </div>
  `, { width: 0.48, position: [0, 0.24, 0.01] });
  root.add(panel.object3D);

  // Five spatial indicators mirror the quiz's progress above the panel.
  const tokenGeometry = new THREE.CylinderGeometry(0.015, 0.015, 0.008, 20);
  tokenGeometry.rotateX(Math.PI / 2);
  const idleMaterial = new THREE.MeshStandardMaterial({
    color: 0x414b5a,
    roughness: 0.65,
  });
  const currentMaterial = new THREE.MeshStandardMaterial({
    color: 0x4b8fe8,
    emissive: 0x173f75,
    emissiveIntensity: 0.45,
    roughness: 0.5,
  });
  const correctMaterial = new THREE.MeshStandardMaterial({
    color: 0x35b879,
    emissive: 0x0d462c,
    emissiveIntensity: 0.35,
    roughness: 0.5,
  });
  const wrongMaterial = new THREE.MeshStandardMaterial({
    color: 0xd65c65,
    emissive: 0x521920,
    emissiveIntensity: 0.3,
    roughness: 0.5,
  });

  const tokens = [];
  const pulses = [0, 0, 0, 0, 0];
  const tokenY = 0.477;
  for (let i = 0; i < questions.length; i++) {
    const token = new THREE.Mesh(tokenGeometry, idleMaterial);
    token.name = `Question ${i + 1} progress`;
    token.position.set((i - 2) * 0.07, tokenY, 0.012);
    root.add(token);
    tokens.push(token);
  }

  let current = 0;
  let score = 0;
  let answered = false;
  let complete = false;
  const results = [null, null, null, null, null];

  function refreshTokens() {
    for (let i = 0; i < tokens.length; i++) {
      if (results[i] === true) {
        tokens[i].material = correctMaterial;
      } else if (results[i] === false) {
        tokens[i].material = wrongMaterial;
      } else if (i === current && !complete) {
        tokens[i].material = currentMaterial;
      } else {
        tokens[i].material = idleMaterial;
      }
    }
  }

  function renderQuestion() {
    const q = questions[current];
    panel.set('progress', { text: `Question ${current + 1} of 5` });
    panel.set('score', { text: `Score: ${score} / 5` });
    panel.set('question', { text: `${q.a} × ${q.b} = ?` });
    panel.set('feedback', {
      text: 'Pinch or poke the correct product.',
      color: '#c7cfda',
    });
    panel.set('next', { display: 'none' });
    panel.set('nextText', { text: 'Next question' });

    for (let i = 0; i < 4; i++) {
      panel.set(`a${i}`, { display: 'flex', backgroundColor: '#303744' });
      panel.set(`a${i}text`, { text: String(q.choices[i]) });
    }
    refreshTokens();
  }

  function chooseAnswer(choiceIndex) {
    if (answered || complete) return;
    answered = true;

    const q = questions[current];
    const chosen = q.choices[choiceIndex];
    const isCorrect = chosen === q.answer;
    results[current] = isCorrect;
    pulses[current] = 1;

    if (isCorrect) score++;
    panel.set('score', { text: `Score: ${score} / 5` });

    for (let i = 0; i < 4; i++) {
      if (q.choices[i] === q.answer) {
        panel.set(`a${i}`, { backgroundColor: '#23845b' });
      } else if (i === choiceIndex) {
        panel.set(`a${i}`, { backgroundColor: '#a7434c' });
      } else {
        panel.set(`a${i}`, { backgroundColor: '#2a2e35' });
      }
    }

    panel.set('feedback', {
      text: isCorrect
        ? `Correct! ${q.a} × ${q.b} = ${q.answer}.`
        : `Not quite. ${q.a} × ${q.b} = ${q.answer}.`,
      color: isCorrect ? '#72dfa9' : '#ff9299',
    });
    panel.set('nextText', {
      text: current === questions.length - 1 ? 'See results' : 'Next question',
    });
    panel.set('next', { display: 'flex' });
    refreshTokens();
  }

  function showResults() {
    complete = true;
    for (let i = 0; i < 4; i++) {
      panel.set(`a${i}`, { display: 'none' });
    }
    panel.set('progress', { text: 'All 5 questions complete' });
    panel.set('score', { text: `Final score: ${score} / 5` });
    panel.set('question', { text: 'Quiz complete!' });

    let message;
    if (score === 5) {
      message = 'Perfect score! You solved every multiplication fact.';
    } else if (score >= 3) {
      message = `Nice work! You answered ${score} of 5 correctly.`;
    } else {
      message = `Good practice! You answered ${score} of 5 correctly. Try again!`;
    }
    panel.set('feedback', { text: message, color: '#ffd477' });
    panel.set('nextText', { text: 'Play again' });
    panel.set('next', { display: 'flex', backgroundColor: '#2f6fdb' });
    refreshTokens();
  }

  function resetQuiz() {
    current = 0;
    score = 0;
    answered = false;
    complete = false;
    for (let i = 0; i < results.length; i++) {
      results[i] = null;
      pulses[i] = 0;
      tokens[i].scale.set(1, 1, 1);
      tokens[i].position.y = tokenY;
    }
    panel.set('next', { backgroundColor: '#2f6fdb' });
    renderQuestion();
  }

  for (let i = 0; i < 4; i++) {
    panel.on(`a${i}`, 'click', () => chooseAnswer(i));
  }

  panel.on('next', 'click', () => {
    if (complete) {
      resetQuiz();
    } else if (answered) {
      if (current === questions.length - 1) {
        showResults();
      } else {
        current++;
        answered = false;
        renderQuestion();
      }
    }
  });

  renderQuestion();

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < tokens.length; i++) {
        if (pulses[i] > 0) {
          pulses[i] = Math.max(0, pulses[i] - delta * 1.4);
          const phase = (1 - pulses[i]) * Math.PI * 3;
          const scale = 1 + Math.sin(phase) * 0.22 * pulses[i];
          tokens[i].scale.set(scale, scale, scale);
          tokens[i].position.y =
            tokenY + Math.abs(Math.sin(phase)) * 0.012 * pulses[i];
        } else {
          tokens[i].scale.set(1, 1, 1);
          tokens[i].position.y = tokenY;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Water molecule builder';

  const O_RADIUS = 0.033;
  const H_RADIUS = 0.024;
  const MIN_BOND_DISTANCE = 0.052;
  const MAX_BOND_DISTANCE = 0.12;

  const oxygenMaterial = new THREE.MeshStandardMaterial({
    color: 0xe94b4b,
    roughness: 0.3,
    metalness: 0.05,
  });
  const hydrogenMaterial = new THREE.MeshStandardMaterial({
    color: 0xf2f4f7,
    roughness: 0.28,
    metalness: 0.03,
  });

  const oxygen = new THREE.Mesh(
    new THREE.SphereGeometry(O_RADIUS, 32, 16),
    oxygenMaterial,
  );
  oxygen.name = 'Oxygen';
  root.add(oxygen);

  const hydrogenGeometry = new THREE.SphereGeometry(H_RADIUS, 24, 12);
  const hydrogen1 = new THREE.Mesh(hydrogenGeometry, hydrogenMaterial);
  hydrogen1.name = 'Hydrogen 1';
  root.add(hydrogen1);

  const hydrogen2 = new THREE.Mesh(hydrogenGeometry, hydrogenMaterial);
  hydrogen2.name = 'Hydrogen 2';
  root.add(hydrogen2);

  const oxygenHome = new THREE.Vector3(-0.07, 0.15, 0.06);
  const hydrogen1Home = new THREE.Vector3(-0.225, 0.065, 0.06);
  const hydrogen2Home = new THREE.Vector3(0.035, 0.065, 0.06);

  const bondGeometry = new THREE.CylinderGeometry(0.0045, 0.0045, 1, 12);
  const bondMaterial = new THREE.MeshStandardMaterial({
    color: 0xc9eaff,
    emissive: 0x376b86,
    emissiveIntensity: 0.35,
    roughness: 0.35,
  });
  const bond1 = new THREE.Mesh(bondGeometry, bondMaterial);
  bond1.name = 'O–H bond 1';
  bond1.visible = false;
  root.add(bond1);

  const bond2 = new THREE.Mesh(bondGeometry, bondMaterial);
  bond2.name = 'O–H bond 2';
  bond2.visible = false;
  root.add(bond2);

  const panel = ui(`
    <style>
      .card {
        display: flex;
        flex-direction: column;
        gap: 12px;
        width: 460px;
        padding-top: 22px;
        padding-bottom: 22px;
        padding-left: 24px;
        padding-right: 24px;
        border-radius: 20px;
        background-color: #1d2127;
        border-color: #3a424e;
        border-width: 2px;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
        text-align: center;
      }
      .body {
        color: #d9dee7;
        font-size: 21px;
      }
      .legend {
        color: #bfc8d4;
        font-size: 19px;
      }
      .formula {
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 12px;
        padding-right: 12px;
        border-radius: 12px;
        background-color: #292f38;
      }
      .formula-text {
        color: #aee2ff;
        font-size: 25px;
        font-weight: 700;
        text-align: center;
      }
      .status {
        color: #d9dee7;
        font-size: 21px;
      }
      .actions {
        display: flex;
        flex-direction: row;
        gap: 12px;
      }
      .check {
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 18px;
        padding-right: 18px;
        border-radius: 12px;
        background-color: #217a58;
      }
      .reset {
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 18px;
        padding-right: 18px;
        border-radius: 12px;
        background-color: #39414c;
      }
      .button-text {
        color: #ffffff;
        font-size: 21px;
        font-weight: 700;
      }
      .tip {
        color: #aeb8c5;
        font-size: 18px;
      }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Pinch and drag the atoms into one bent H–O–H group.</span>
      <span class="legend">Large red sphere = oxygen (O) · Small white spheres = hydrogen (H)</span>
      <div class="formula">
        <span class="formula-text">Target: H₂O · bond angle 104.5°</span>
      </div>
      <span class="status" id="status">Bring both hydrogen atoms close to oxygen, then press Check.</span>
      <div class="actions">
        <button class="check" id="check"><span class="button-text">Check molecule</span></button>
        <button class="reset" id="reset"><span class="button-text">Reset</span></button>
      </div>
      <span class="tip">Tip: oxygen sits in the middle. The two O–H bonds should form an angle, not a straight line.</span>
    </div>
  `, {
    width: 0.32,
    position: [0.25, 0.22, -0.025],
    rotationY: -0.25,
  });
  root.add(panel.object3D);

  traits(oxygen, { grab: true });
  traits(hydrogen1, { grab: true });
  traits(hydrogen2, { grab: true });

  const toH1 = new THREE.Vector3();
  const toH2 = new THREE.Vector3();
  const bondDirection = new THREE.Vector3();
  const bondMidpoint = new THREE.Vector3();
  const yAxis = new THREE.Vector3(0, 1, 0);
  let succeeded = false;
  let wasHeld = false;

  function setBond(mesh, hydrogen) {
    bondDirection.subVectors(hydrogen.position, oxygen.position);
    const distance = bondDirection.length();
    bondMidpoint.addVectors(oxygen.position, hydrogen.position).multiplyScalar(0.5);
    mesh.position.copy(bondMidpoint);
    mesh.scale.set(1, Math.max(0.005, distance - O_RADIUS - H_RADIUS), 1);
    bondDirection.normalize();
    mesh.quaternion.setFromUnitVectors(yAxis, bondDirection);
  }

  function showStatus(text, color) {
    panel.set('status', { text, color });
  }

  function reset() {
    oxygen.position.copy(oxygenHome);
    hydrogen1.position.copy(hydrogen1Home);
    hydrogen2.position.copy(hydrogen2Home);
    succeeded = false;
    bond1.visible = false;
    bond2.visible = false;
    showStatus('Bring both hydrogen atoms close to oxygen, then press Check.', '#d9dee7');
  }

  function checkMolecule() {
    succeeded = false;
    bond1.visible = false;
    bond2.visible = false;

    if (isGrabbed(oxygen) || isGrabbed(hydrogen1) || isGrabbed(hydrogen2)) {
      showStatus('Release the atoms first, then press Check.', '#ffd27d');
      return;
    }

    toH1.subVectors(hydrogen1.position, oxygen.position);
    toH2.subVectors(hydrogen2.position, oxygen.position);
    const distance1 = toH1.length();
    const distance2 = toH2.length();

    if (distance1 < MIN_BOND_DISTANCE || distance2 < MIN_BOND_DISTANCE) {
      showStatus('Not water yet: the atoms overlap. Separate their centers slightly.', '#ffd27d');
      return;
    }

    if (distance1 > MAX_BOND_DISTANCE || distance2 > MAX_BOND_DISTANCE) {
      showStatus('Not water yet: move each hydrogen close enough to oxygen to form an O–H bond.', '#ffd27d');
      return;
    }

    const cosine = THREE.MathUtils.clamp(
      toH1.dot(toH2) / (distance1 * distance2),
      -1,
      1,
    );
    const angle = THREE.MathUtils.radToDeg(Math.acos(cosine));

    if (angle < 80 || angle > 130) {
      showStatus('Not water yet: make the H–O–H group bent, close to 104.5°—not straight or tightly folded.', '#ffd27d');
      return;
    }

    succeeded = true;
    bond1.visible = true;
    bond2.visible = true;
    setBond(bond1, hydrogen1);
    setBond(bond2, hydrogen2);
    showStatus(
      `Yes — you built water (H₂O)! Two O–H bonds, with an angle of ${Math.round(angle)}°.`,
      '#82efb2',
    );
  }

  panel.on('check', 'click', checkMolecule);
  panel.on('reset', 'click', reset);
  reset();

  return {
    root,
    update() {
      const held = isGrabbed(oxygen) || isGrabbed(hydrogen1) || isGrabbed(hydrogen2);

      if (held && !wasHeld) {
        succeeded = false;
        bond1.visible = false;
        bond2.visible = false;
        showStatus('Arrange the atoms, release them, then press Check.', '#d9dee7');
      }

      if (succeeded && !held) {
        setBond(bond1, hydrogen1);
        setBond(bond2, hydrogen2);
      }

      wasHeld = held;
    },
  };
}

