        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: center;
        gap: 6px;
      }
      .corner {
        width: 146px;
        color: #97a3b2;
        font-size: 20px;
        font-weight: 700;
      }
      .dayHeader {
        width: 48px;
        color: #b8c1cc;
        font-size: 20px;
        font-weight: 700;
        text-align: center;
      }
      .habitLabel {
