        flex-direction: column;
        align-items: flex-start;
        gap: 1px;
        width: 146px;
      }
      .habitName {
        color: #ffffff;
        font-size: 24px;
        font-weight: 700;
      }
      .habitGoal {
        color: #aeb7c2;
        font-size: 20px;
      }
