        height: 46px;
        border-radius: 12px;
        border-width: 2px;
        border-color: #3a424d;
        background-color: #2a2e35;
      }
      .dayMark {
        color: #8e99a8;
        font-size: 25px;
        font-weight: 700;
        text-align: center;
      }
