      </div>
    </div>
  `, {
    width: 0.47,
    position: [0, 0.23, 0.002],
  });
  root.add(tracker.object3D);

  function latestStreak(checks) {
    let end = checks.length - 1;
    while (end >= 0 && !checks[end]) end--;
    if (end < 0) return 0;

    let streak = 0;
    for (let day = end; day >= 0 && checks[day]; day--) {
      streak++;
    }
    return streak;
  }

  function updateDay(habitIndex, dayIndex) {
    const habit = habits[habitIndex];
    const checked = habit.checks[dayIndex];

    tracker.set(`day${habitIndex}${dayIndex}`, {
      backgroundColor: checked ? habit.color : '#2a2e35',
    });
    tracker.set(`mark${habitIndex}${dayIndex}`, {
      text: checked ? '✓' : '○',
      color: checked ? '#121820' : '#8e99a8',
    });
  }

  function updateStreak(habitIndex) {
    const habit = habits[habitIndex];
    const streak = latestStreak(habit.checks);
    tracker.set(`streak${habitIndex}`, {
      text: `Streak: ${streak} ${streak === 1 ? 'day' : 'days'}`,
      color: streak > 0 ? habit.color : '#97a3b2',
    });
  }

  function updateProgress() {
    let completed = 0;
    for (const habit of habits) {
      for (const checked of habit.checks) {
        if (checked) completed++;
      }
    }
    tracker.set('progress', {
      text: `${completed} / 21 check-offs`,
      color: completed === 21 ? '#67d29a' : '#d7dce3',
    });
  }

  function renderAll() {
    habits.forEach((habit, habitIndex) => {
      habit.checks.forEach((checked, dayIndex) => updateDay(habitIndex, dayIndex));
      updateStreak(habitIndex);
    });
    updateProgress();
  }

  habits.forEach((habit, habitIndex) => {
    habit.checks.forEach((checked, dayIndex) => {
      tracker.on(`day${habitIndex}${dayIndex}`, 'click', () => {
        habit.checks[dayIndex] = !habit.checks[dayIndex];
        updateDay(habitIndex, dayIndex);
        updateStreak(habitIndex);
        updateProgress();
      });
    });
  });

  tracker.on('clear', 'click', () => {
    for (const habit of habits) {
      habit.checks.fill(false);
    }
    renderAll();
  });

  renderAll();
  return { root };
}

