      new THREE.Vector3(0, 0.023, 0),
      new THREE.Vector3(0.035, 0.012, 0),
      new THREE.Vector3(0.055, -0.008, 0),
    ]);
    const body = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 20, 0.013, 8, false),
      new THREE.MeshStandardMaterial({ color: 0xf2cf3c, roughness: 0.65 }),
    );
    body.name = 'Banana body';
    group.add(body);

    const tipGeometry = new THREE.SphereGeometry(0.014, 12, 8);
    const tipMaterial = new THREE.MeshStandardMaterial({ color: 0x705126, roughness: 0.9 });
    [-0.055, 0.055].forEach((x) => {
      const tip = new THREE.Mesh(tipGeometry, tipMaterial);
      tip.scale.set(0.55, 0.72, 0.72);
      tip.position.set(x, -0.008, 0);
      group.add(tip);
    });
    return group;
  }

  const fruits = [
    {
      name: 'Apple',
      price: 120,
      object: makeApple(),
      home: new THREE.Vector3(-0.26, 0.05, 0.055),
      slot: new THREE.Vector3(BASKET_X - 0.065, 0.064, BASKET_Z + 0.035),
      homeYaw: 0,
      slotYaw: -0.25,
    },
    {
      name: 'Banana',
      price: 60,
      object: makeBanana(),
      home: new THREE.Vector3(-0.12, 0.04, 0.055),
      slot: new THREE.Vector3(BASKET_X + 0.015, 0.052, BASKET_Z - 0.038),
      homeYaw: -0.2,
      slotYaw: 0.35,
    },
    {
      name: 'Orange',
      price: 90,
      object: makeOrange(),
      home: new THREE.Vector3(0.02, 0.046, 0.055),
      slot: new THREE.Vector3(BASKET_X + 0.065, 0.064, BASKET_Z + 0.035),
      homeYaw: 0,
      slotYaw: 0.4,
    },
  ];

  fruits.forEach((fruit) => {
    fruit.inBasket = false;
    fruit.wasGrabbed = false;
    fruit.object.position.copy(fruit.home);
    fruit.object.rotation.y = fruit.homeYaw;
    root.add(fruit.object);
    traits(fruit.object, { grab: true });
  });

  let totalCents = 0;

  function money(cents) {
    return `$${(cents / 100).toFixed(2)}`;
  }

  function refreshReceipt() {
    const included = fruits.filter((fruit) => fruit.inBasket);
    totalCents = included.reduce((sum, fruit) => sum + fruit.price, 0);
    panel.set('receipt', {
      text: included.length
        ? `Basket: ${included.map((fruit) => fruit.name).join(', ')}`
        : 'Basket: empty',
    });
    panel.set('total', { text: `Total: ${money(totalCents)}` });
  }

  function isOverBasket(position) {
    return Math.abs(position.x - BASKET_X) < 0.15 &&
      Math.abs(position.z - BASKET_Z) < 0.12 &&
      position.y >= 0 && position.y < 0.32;
  }

  panel.on('empty', 'click', () => {
    fruits.forEach((fruit) => {
      fruit.inBasket = false;
      if (!isGrabbed(fruit.object)) {
        fruit.wasGrabbed = false;
        fruit.object.position.copy(fruit.home);
        fruit.object.rotation.set(0, fruit.homeYaw, 0);
      } else {
        fruit.wasGrabbed = true;
      }
    });
    refreshReceipt();
    panel.set('status', { text: 'Basket emptied. Grab a fruit to start again.' });
  });

  refreshReceipt();

  return {
    root,
    update(time) {
      let anyHeld = false;

      for (const fruit of fruits) {
        const grabbed = isGrabbed(fruit.object);
        if (grabbed) {
          anyHeld = true;
          fruit.wasGrabbed = true;
          if (fruit.inBasket) {
            fruit.inBasket = false;
            refreshReceipt();
            panel.set('status', { text: `${fruit.name} removed from the basket.` });
          }
        } else if (fruit.wasGrabbed) {
          fruit.wasGrabbed = false;
          if (isOverBasket(fruit.object.position)) {
            fruit.object.position.copy(fruit.slot);
            fruit.object.rotation.set(0, fruit.slotYaw, 0);
            fruit.inBasket = true;
            refreshReceipt();
            panel.set('status', { text: `${fruit.name} added to the basket.` });
          }
        }
      }

      const pulse = 0.5 + 0.5 * Math.sin(time * 4);
      dropRing.material.opacity = anyHeld ? 0.14 + pulse * 0.14 : 0.035;
      wicker.emissive.setHex(anyHeld ? 0x163625 : 0x000000);
      wicker.emissiveIntensity = anyHeld ? 0.35 + pulse * 0.25 : 0;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const OXYGEN_RADIUS = 0.047;
  const HYDROGEN_RADIUS = 0.031;
  const BOND_DISTANCE = 0.09;
  const BOND_MIN = 0.062;
  const BOND_MAX = 0.113;
  const SNAP_RADIUS = 0.065;
  const HALF_ANGLE = THREE.MathUtils.degToRad(52.25);
  const TARGET_X = BOND_DISTANCE * Math.sin(HALF_ANGLE);
  const TARGET_Y = -BOND_DISTANCE * Math.cos(HALF_ANGLE);

  const oxygen = new THREE.Mesh(
    new THREE.SphereGeometry(OXYGEN_RADIUS, 32, 16),
    new THREE.MeshStandardMaterial({
      color: 0xe34f4f,
      roughness: 0.38,
      metalness: 0.05,
      emissive: 0x320707,
      emissiveIntensity: 0.2,
    }),
  );
  oxygen.name = 'Oxygen';
  root.add(oxygen);

  const hydrogenGeometry = new THREE.SphereGeometry(HYDROGEN_RADIUS, 24, 12);
  const hydrogenMaterial = new THREE.MeshStandardMaterial({
    color: 0xf2f5f7,
    roughness: 0.35,
    metalness: 0.04,
  });

  const hydrogen1 = new THREE.Mesh(hydrogenGeometry, hydrogenMaterial);
  hydrogen1.name = 'Hydrogen 1';
  root.add(hydrogen1);

  const hydrogen2 = new THREE.Mesh(hydrogenGeometry, hydrogenMaterial);
  hydrogen2.name = 'Hydrogen 2';
  root.add(hydrogen2);

  const hydrogens = [hydrogen1, hydrogen2];
  const oxygenStart = new THREE.Vector3(-0.085, 0.19, 0);
  const hydrogenStarts = [
    new THREE.Vector3(-0.255, 0.043, 0.12),
    new THREE.Vector3(0.02, 0.043, 0.12),
  ];

  oxygen.position.copy(oxygenStart);
  hydrogen1.position.copy(hydrogenStarts[0]);
  hydrogen2.position.copy(hydrogenStarts[1]);

  const targetPositions = [new THREE.Vector3(), new THREE.Vector3()];
  const guides = [];
  const guideGeometry = new THREE.TorusGeometry(0.037, 0.002, 8, 32);

  for (let i = 0; i < 2; i++) {
    const guide = new THREE.Mesh(
      guideGeometry,
      new THREE.MeshBasicMaterial({
        color: 0x68d8ff,
        transparent: true,
        opacity: 0.4,
        depthWrite: false,
      }),
    );
    guide.name = 'Hydrogen placement guide ' + (i + 1);
    root.add(guide);
    guides.push(guide);
  }

  const bondGeometry = new THREE.CylinderGeometry(0.006, 0.006, 1, 12);
  const bondMaterial = new THREE.MeshStandardMaterial({
    color: 0xbac6cf,
    roughness: 0.45,
    metalness: 0.15,
  });
  const bonds = [];

  for (let i = 0; i < 2; i++) {
    const bond = new THREE.Mesh(bondGeometry, bondMaterial);
    bond.name = 'O–H bond ' + (i + 1);
    bond.visible = false;
    root.add(bond);
    bonds.push(bond);
  }

  const padMaterial = new THREE.MeshStandardMaterial({
    color: 0x26323d,
    roughness: 0.8,
  });
  const oxygenPad = new THREE.Mesh(
    new THREE.CylinderGeometry(0.059, 0.059, 0.01, 32),
    padMaterial,
  );
  oxygenPad.position.set(oxygenStart.x, 0.005, oxygenStart.z);
  root.add(oxygenPad);

  const hydrogenPadGeometry = new THREE.CylinderGeometry(0.04, 0.04, 0.01, 24);
  for (let i = 0; i < 2; i++) {
    const pad = new THREE.Mesh(hydrogenPadGeometry, padMaterial);
    pad.position.set(hydrogenStarts[i].x, 0.005, hydrogenStarts[i].z);
    root.add(pad);
  }

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 11px; width: 470px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1f242b;
              border-color: #3b4652; border-width: 2px; }
      .title { color: #ffffff; font-size: 31px; font-weight: 700; }
      .goal { color: #8fd8ff; font-size: 24px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 20px; }
      .readout { color: #ffffff; font-size: 21px; font-weight: 700; }
      .status { color: #d7dbe2; font-size: 21px; }
      .fact { color: #aeb8c4; font-size: 18px; }
      .row { flex-direction: row; gap: 12px; }
      .btn { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2878c8;
             border-color: #64a9e8; border-width: 1px; }
      .secondary { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px;
                   border-radius: 12px; background-color: #343c46;
                   border-color: #596674; border-width: 1px; }
      .btnText { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="goal">Goal: H₂O = 2 hydrogen + 1 oxygen</span>
      <span class="body">Pinch-drag each white H onto a cyan ring around the red O, then press Check.</span>
      <span class="readout" id="connections">O–H connections: 0 / 2</span>
      <span class="status" id="status">Both H atoms must connect directly to the O atom.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btnText">Check molecule</span></button>
        <button class="secondary" id="reset"><span class="btnText">Reset</span></button>
      </div>
      <span class="fact">Real water is bent: its H–O–H angle is about 104.5°.</span>
    </div>`, {
    width: 0.34,
    position: [0.235, 0.22, 0.02],
    rotationY: -0.3,
  });
  root.add(panel.object3D);

  let checked = false;
  let lastBondCount = -1;
  let oxygenWasGrabbed = false;
  hydrogen1.userData.wasGrabbed = false;
  hydrogen2.userData.wasGrabbed = false;

  const connectionLabels = [
    { text: 'O–H connections: 0 / 2' },
    { text: 'O–H connections: 1 / 2' },
    { text: 'O–H connections: 2 / 2' },
  ];
  const changedStatus = {
    text: 'Molecule changed — press Check when ready.',
    color: '#d7dbe2',
  };

  function markDirty() {
    if (checked) {
      checked = false;
      panel.set('status', changedStatus);
    }
  }

  function validBondDistance(distance) {
    return distance >= BOND_MIN && distance <= BOND_MAX;
  }

  const bondDirection = new THREE.Vector3();
  const bondMidpoint = new THREE.Vector3();
  const upAxis = new THREE.Vector3(0, 1, 0);
  const checkDirection1 = new THREE.Vector3();
  const checkDirection2 = new THREE.Vector3();

  panel.on('check', 'click', () => {
    const distance1 = oxygen.position.distanceTo(hydrogen1.position);
    const distance2 = oxygen.position.distanceTo(hydrogen2.position);
    const bonded1 = validBondDistance(distance1);
    const bonded2 = validBondDistance(distance2);
    checked = true;

    if (distance1 < BOND_MIN || distance2 < BOND_MIN) {
      panel.set('status', {
        text: 'Not yet: atoms are overlapping. Give each H its own cyan guide.',
        color: '#ffd166',
      });
      return;
    }

    if (bonded1 && bonded2) {
      checkDirection1.copy(hydrogen1.position).sub(oxygen.position).normalize();
      checkDirection2.copy(hydrogen2.position).sub(oxygen.position).normalize();
      const dot = THREE.MathUtils.clamp(checkDirection1.dot(checkDirection2), -1, 1);
      const angle = THREE.MathUtils.radToDeg(Math.acos(dot));

      if (angle >= 85 && angle <= 125) {
        panel.set('status', {
          text: 'Yes — H₂O! Two O–H bonds in a bent shape. Your angle is ' + angle.toFixed(1) + '°.',
          color: '#7ce3a1',
        });
      } else {
        panel.set('status', {
          text: 'Close: two O–H bonds, but water needs a bent angle near 104.5°. Use both guides.',
          color: '#ffd166',
        });
      }
    } else if (bonded1 || bonded2) {
      panel.set('status', {
        text: 'Not water yet: only one O–H connection. Bring the second H to the oxygen.',
        color: '#ffd166',
      });
    } else {
      panel.set('status', {
        text: 'Not water yet: connect both H atoms directly to the single O atom.',
        color: '#ffd166',
      });
    }
  });

  panel.on('reset', 'click', () => {
    oxygen.position.copy(oxygenStart);
    hydrogen1.position.copy(hydrogenStarts[0]);
    hydrogen2.position.copy(hydrogenStarts[1]);
    oxygenWasGrabbed = false;
    hydrogen1.userData.wasGrabbed = false;
    hydrogen2.userData.wasGrabbed = false;
    checked = false;
    lastBondCount = -1;
    panel.set('status', {
      text: 'Atoms reset. Place both white H atoms on the cyan guides.',
      color: '#8fd8ff',
    });
  });

  traits(oxygen, {
    grab: true,
    onPress: () => {
      panel.set('status', {
        text: 'Oxygen (O) is the red atom. Every water molecule contains one oxygen atom.',
        color: '#8fd8ff',
      });
    },
  });

  for (let i = 0; i < hydrogens.length; i++) {
    traits(hydrogens[i], {
      grab: true,
      onPress: () => {
        panel.set('status', {
          text: 'Hydrogen (H) is a white atom. Water needs two hydrogen atoms bonded to one oxygen.',
          color: '#8fd8ff',
        });
      },
    });
  }

  return {
    root,
    update(time) {
      targetPositions[0].set(
        oxygen.position.x - TARGET_X,
        oxygen.position.y + TARGET_Y,
        oxygen.position.z,
      );
      targetPositions[1].set(
        oxygen.position.x + TARGET_X,
        oxygen.position.y + TARGET_Y,
        oxygen.position.z,
      );

      const oxygenGrabbed = isGrabbed(oxygen);
      if (oxygenGrabbed && !oxygenWasGrabbed) markDirty();
      oxygenWasGrabbed = oxygenGrabbed;

      for (let i = 0; i < 2; i++) {
        const hydrogen = hydrogens[i];
        const grabbed = isGrabbed(hydrogen);

        if (grabbed && !hydrogen.userData.wasGrabbed) markDirty();

        if (!grabbed && hydrogen.userData.wasGrabbed) {
          let nearest = -1;
          let bestDistanceSquared = SNAP_RADIUS * SNAP_RADIUS;

          for (let j = 0; j < 2; j++) {
            const distanceSquared = hydrogen.position.distanceToSquared(targetPositions[j]);
            if (distanceSquared < bestDistanceSquared) {
              bestDistanceSquared = distanceSquared;
              nearest = j;
            }
          }

          if (nearest >= 0) {
            const other = hydrogens[1 - i];
            const targetOccupied =
              other.position.distanceToSquared(targetPositions[nearest]) < 0.04 * 0.04;
            if (!targetOccupied) hydrogen.position.copy(targetPositions[nearest]);
          }
        }

        hydrogen.userData.wasGrabbed = grabbed;
      }

      let bondCount = 0;
      for (let i = 0; i < 2; i++) {
        const distance = oxygen.position.distanceTo(hydrogens[i].position);
        const bonded = validBondDistance(distance);
        bonds[i].visible = bonded;

        if (bonded) {
          bondCount++;
          bondMidpoint.copy(oxygen.position).add(hydrogens[i].position).multiplyScalar(0.5);
          bondDirection.copy(hydrogens[i].position).sub(oxygen.position).normalize();
          bonds[i].position.copy(bondMidpoint);
          bonds[i].scale.set(1, distance, 1);
          bonds[i].quaternion.setFromUnitVectors(upAxis, bondDirection);
        }
      }

      if (bondCount !== lastBondCount) {
        lastBondCount = bondCount;
        panel.set('connections', connectionLabels[bondCount]);
      }

      for (let i = 0; i < 2; i++) {
        guides[i].position.copy(targetPositions[i]);
        const occupied =
          hydrogen1.position.distanceToSquared(targetPositions[i]) < 0.04 * 0.04 ||
          hydrogen2.position.distanceToSquared(targetPositions[i]) < 0.04 * 0.04;

        guides[i].material.color.setHex(occupied ? 0x73e2a7 : 0x68d8ff);
        guides[i].material.opacity = occupied ? 0.24 : 0.36 + Math.sin(time * 2.2) * 0.08;
      }
    },
  };
}

