    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint" id="hint">Pinch a fruit, then release it over the basket. Pick it out to remove it.</span>
      <div class="row"><span class="item">Apple</span><span class="price">$0.75</span></div>
      <div class="row"><span class="item">Orange</span><span class="price">$0.60</span></div>
      <div class="row"><span class="item">Banana</span><span class="price">$0.45</span></div>
      <div class="total-row"><span class="total-label">Basket total</span><span class="total" id="total">$0.00</span></div>
      <span class="contents" id="contents">Basket is empty.</span>
      <button class="button" id="empty"><span class="button-text">Empty basket</span></button>
    </div>`, { width: 0.38, position: [0, 0.31, -0.16] });
  root.add(info.object3D);

  const fruits = [
    {
      label: 'Apple', priceCents: 75, object: makeApple(),
      homeX: -0.27, homeZ: 0.075, restY: 0.032,
      slotX: 0.145, slotY: 0.049, slotZ: 0.025,
      inBasket: false, wasGrabbed: false,
    },
    {
      label: 'Orange', priceCents: 60, object: makeOrange(),
      homeX: -0.16, homeZ: 0.075, restY: 0.031,
      slotX: 0.230, slotY: 0.047, slotZ: 0.025,
      inBasket: false, wasGrabbed: false,
    },
    {
      label: 'Banana', priceCents: 45, object: makeBanana(),
      homeX: -0.05, homeZ: 0.075, restY: 0.012,
      slotX: 0.188, slotY: 0.088, slotZ: 0.025,
      inBasket: false, wasGrabbed: false,
    },
  ];

  for (let i = 0; i < fruits.length; i++) {
    const fruit = fruits[i];
    fruit.object.position.set(fruit.homeX, fruit.restY, fruit.homeZ);
    root.add(fruit.object);
    traits(fruit.object, { grab: true });
  }

  const markerGeometry = new THREE.CylinderGeometry(0.041, 0.041, 0.002, 24);
  const markerMaterial = new THREE.MeshStandardMaterial({ color: 0x414751, roughness: 0.9 });
  const markers = new THREE.InstancedMesh(markerGeometry, markerMaterial, fruits.length);
  const markerMatrix = new THREE.Matrix4();
  for (let i = 0; i < fruits.length; i++) {
    markerMatrix.makeTranslation(fruits[i].homeX, 0.001, fruits[i].homeZ);
    markers.setMatrixAt(i, markerMatrix);
  }
  markers.instanceMatrix.needsUpdate = true;
  root.add(markers);

  function money(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  function refreshBasket() {
    let cents = 0;
    let count = 0;
    let names = '';

    for (let i = 0; i < fruits.length; i++) {
      const fruit = fruits[i];
      if (fruit.inBasket) {
        cents += fruit.priceCents;
        count++;
        names += (names ? ', ' : '') + fruit.label;
      }
    }

    info.set('total', { text: money(cents) });
    info.set('contents', {
      text: count === 0
        ? 'Basket is empty.'
        : count + (count === 1 ? ' item: ' : ' items: ') + names,
    });
  }

  function isOverBasket(position) {
    return Math.abs(position.x - 0.19) < 0.105 &&
      Math.abs(position.z + 0.015) < 0.085 &&
      position.y > 0 && position.y < 0.42;
  }

  info.on('empty', 'click', () => {
    let changed = false;
    for (let i = 0; i < fruits.length; i++) {
      const fruit = fruits[i];
      if (fruit.inBasket && !isGrabbed(fruit.object)) {
        fruit.inBasket = false;
        fruit.wasGrabbed = false;
        fruit.object.position.set(fruit.homeX, fruit.restY, fruit.homeZ);
        fruit.object.rotation.set(0, 0, 0);
        changed = true;
      }
    }
    if (changed) refreshBasket();
  });

  const defaultHint = 'Pinch a fruit, then release it over the basket. Pick it out to remove it.';
  let lastDropHint = null;
  refreshBasket();

  return {
    root,
    update() {
      let changed = false;
      let heldOver = null;

      for (let i = 0; i < fruits.length; i++) {
        const fruit = fruits[i];
        const object = fruit.object;
        const grabbed = isGrabbed(object);

        if (grabbed) {
          if (!fruit.wasGrabbed) {
            fruit.wasGrabbed = true;
            if (fruit.inBasket) {
              fruit.inBasket = false;
              changed = true;
            }
          }
          if (isOverBasket(object.position)) heldOver = fruit.label;
          continue;
        }

        if (fruit.wasGrabbed) {
          fruit.wasGrabbed = false;
          object.rotation.set(0, 0, 0);

          if (isOverBasket(object.position)) {
            fruit.inBasket = true;
            object.position.set(fruit.slotX, fruit.slotY, fruit.slotZ);
          } else {
            fruit.inBasket = false;
            object.position.x = Math.max(-0.34, Math.min(0.34, object.position.x));
            object.position.z = Math.max(-0.14, Math.min(0.17, object.position.z));
            object.position.y = fruit.restY;
          }
          changed = true;
        }
      }

      if (changed) refreshBasket();

      if (heldOver !== lastDropHint) {
        if (heldOver) {
          info.set('hint', { text: 'Release to add ' + heldOver + '.', color: '#b7f398' });
        } else {
          info.set('hint', { text: defaultHint, color: '#d6dbe3' });
        }
        lastDropHint = heldOver;
      }

      const highlighted = heldOver !== null;
      rimMaterial.emissive.setHex(highlighted ? 0x4f8a2d : 0x1a0d02);
      rimMaterial.emissiveIntensity = highlighted ? 0.75 : 0.25;
    },
  };
}
